def propose_rule_candidates(s_in, s_out):
    """Generate candidate rules from a transformation."""
    candidates = []

    # Look for simple patterns: insertions, deletions, substitutions

    # Case 1: Check if s_out is s_in with prefix added
    if s_out.startswith(s_in):
        prefix = s_out[len(s_in):]
        if len(prefix) <= 3:
            candidates.append(("", prefix, 0))

    # Case 2: Check if s_out is s_in with suffix added  
    if s_out.endswith(s_in):
        suffix = s_out[:-len(s_in)]
        if len(suffix) <= 3:
            candidates.append(("", suffix, len(s_in)))

    # Case 3: Look for single character substitutions
    if len(s_in) == len(s_out):
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                old_char = s_in[i]
                new_char = s_out[i]
                candidates.append((old_char, new_char, i))

    # Case 4: Look for substring replacements
    # Try replacing various substrings
    for length in range(1, min(len(s_in), len(s_out)) + 1):
        for i in range(len(s_in) - length + 1):
            old_sub = s_in[i:i+length]
            # Check if this substring appears in s_out at some position
            for j in range(len(s_out) - length + 1):
                if s_out[j:j+length] == old_sub:
                    # Check if replacing this makes sense
                    # We want to replace old_sub with new_sub where new_sub = s_out[j:j+length]
                    # But since they're equal, this is just a positioning issue
                    pass

    # Add general candidates
    # If s_out is longer than s_in, it could be appending
    if len(s_out) > len(s_in):
        append_str = s_out[len(s_in):]
        if len(append_str) <= 3:
            candidates.append(("", append_str, len(s_in)))

    # If s_out is shorter than s_in, it could be deleting
    if len(s_out) < len(s_in):
        delete_str = s_in[len(s_out):]
        if len(delete_str) <= 3:
            candidates.append((delete_str, "", 0))

    # Also add direct replacements if they exist
    if s_in != s_out:
        candidates.append((s_in, s_out, -1))  # General replacement

    # Remove duplicates and sort by specificity
    unique_candidates = []
    seen = set()
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    # Sort by specificity (more specific first)
    # Simpler rules first
    def sort_key(cand):
        pattern, replacement, pos = cand
        # Prefer shorter patterns and replacements
        return (len(pattern), len(replacement))

    unique_candidates.sort(key=sort_key)
    return unique_candidates

